@Component("role-handler")
@ProcessingGroup("role-processing-group")
public class RoleEventHandler {
	
	// core constructor
	RoleEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateRoleEvent
     */
    @EventHandler
    public void handle( CreateRoleEvent event) {
        entityManager.persist(new Role(event.getRoleId(), event.getName(), event.getResponsibility(), event.getAssignments()));
    }

    /*
     * @param	event UpdateRoleEvent
     */
    @EventHandler
    public Role handle( UpdateRoleEvent event) {
    	entityManager.merge(new Role(event.getRoleId(), event.getName(), event.getResponsibility(), event.getAssignments()));
    }
    
    /*
     * @param	event DeleteRoleEvent
     */
    @EventHandler
    public void on( DeleteRoleEvent event) {
    	Role entity = new Role();
   
    	// ------------------------------------------
    	// apply the RoleId
    	// ------------------------------------------
    	entity.setRoleId( event.getRoleId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final RoleRepository roleEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(RoleEventHandler.class.getName());

}
